style.css:
@-moz-document domain("roblox.com") {
/* Base background and fonts */
body, html {
    background-color: #E7EEF8 !important;
    color: #000 !important;
    font-family: Verdana, Arial, sans-serif !important;
}

/* Links */
a, a:visited {
    color: #0033cc !important;
    text-decoration: underline !important;
}

/* Headers */
h1, h2, h3, h4, h5, h6 {
    color: #000080 !important;
    font-weight: bold !important;
    border-bottom: 1px solid #C1D9FF !important;
    padding-bottom: 4px !important;
}

/* Navbar */
nav, .navbar, header, #header, .top-nav {
    background-color: #C1D9FF !important;
    border-bottom: 2px solid #99BBFF !important;
    color: #000 !important;
    font-size: 14px !important;
    padding: 10px !important;
    box-shadow: 0 2px 5px rgba(0,0,0,0.1) !important;
}

/* Buttons */
button, .btn, .btn-primary, .btn-secondary {
    background-color: #99BBFF !important;
    color: #000000 !important;
    border: 1px solid #0033cc !important;
    border-radius: 5px !important;
    font-weight: bold !important;
    padding: 5px 10px !important;
}

/* Inputs and forms */
input, textarea, select {
    background-color: #ffffff !important;
    color: #000000 !important;
    border: 1px solid #99BBFF !important;
    padding: 4px !important;
}

/* Game cards */
.game-card-container, .game-tile, .thumbnail-container {
    background-color: #DDEAFF !important;
    border: 1px solid #99BBFF !important;
    border-radius: 5px !important;
    box-shadow: 2px 2px 5px rgba(0,0,0,0.05) !important;
}

/* Footer */
footer, #footer {
    background-color: #C1D9FF !important;
    color: #000 !important;
    border-top: 2px solid #99BBFF !important;
    padding: 15px !important;
}

/* Sidebar and containers */
.side-nav, .sidebar, .container, .section, .panel {
    background-color: #F0F5FF !important;
    border: 1px solid #C1D9FF !important;
    padding: 10px !important;
    border-radius: 5px !important;
}

/* Scrollbar */
::-webkit-scrollbar {
    width: 12px;
}
::-webkit-scrollbar-track {
    background: #E7EEF8 !important;
}
::-webkit-scrollbar-thumb {
    background-color: #99BBFF !important;
    border: 2px solid #C1D9FF !important;
}

/* Logo override */
#header .logo img {
    content: url("https://images.wikia.com/roblox/images/archive/4/43/20110703052000!RobloxLogoOld.png") !important;
    height: 40px !important;
}

/* Restore legacy feel */
#navigation-container, .top-nav, .navigation-bar, .header {
    background-color: #C1D9FF !important;
    font-size: 13px !important;
    font-weight: bold !important;
    text-align: left !important;
}
}
